FuncDef.Code:
void opAnimRotate(inout vec3 p, in vec3 animSpeed, in vec3 animOffset)
{
    vec3 rotation = 2.0 * PI * animSpeed * iTime + animOffset;

    float sinX = sin(-rotation.x);
    float cosX = cos(-rotation.x);

    float sinY = sin(-rotation.y);
    float cosY = cos(-rotation.y);

    float sinZ = sin(-rotation.z);
    float cosZ = cos(-rotation.z);

    mat3 rX = mat3(1,0,0, 0,cosX,-sinX, 0,sinX,cosX);
    mat3 rY = mat3(cosY,0,sinY, 0,1,0, -sinY,0,cosY);
    mat3 rZ = mat3(cosZ,-sinZ,0, sinZ,cosZ,0, 0,0,1);

    mat3 rot = rY * rX * rZ;

    //p *= rot;
    p = SDFG_MUL(rot, p);
}
